"""Heat diffusion on the GPU.

Usage: python main.py <grid-file>

The grid file holds "<width> <height> <steps>" followed by height rows of
width whole numbers. Each step replaces every cell with
(4 * self + left + right + up + down) // 8, computed by a compute shader.
Edge cells read themselves for a missing neighbour. The finished grid is
written to stdout, followed by "SUM <total>".
"""

import sys

import numpy as np
import wgpu

WORKGROUP = 16

SHADER = """
struct Params {
    width: u32,
    height: u32,
    pad0: u32,
    pad1: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(%(wg)d, %(wg)d)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= params.width || y >= params.height) {
        return;
    }
    let w = params.width;
    let h = params.height;
    let xl = select(x - 1u, x, x == 0u);
    let xr = select(x + 1u, x, x + 1u >= w);
    let yu = select(y - 1u, y, y == 0u);
    let yd = select(y + 1u, y, y + 1u >= h);

    let centre = src[y * w + x];
    let left = src[y * w + xl];
    let right = src[y * w + xr];
    let up = src[yu * w + x];
    let down = src[yd * w + x];

    dst[y * w + x] = (4u * centre + left + right + up + down) / 8u;
}
""" % {"wg": WORKGROUP}


def read_grid(path):
    with open(path, "r") as f:
        tokens = f.read().split()
    width, height, steps = int(tokens[0]), int(tokens[1]), int(tokens[2])
    values = np.array(tokens[3 : 3 + width * height], dtype=np.uint32)
    if values.size != width * height:
        raise ValueError(f"expected {width * height} cells, got {values.size}")
    return width, height, steps, values


def diffuse(width, height, steps, values):
    device = wgpu.gpu.request_adapter_sync(
        power_preference="high-performance"
    ).request_device_sync()

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto",
        compute={"module": module, "entry_point": "main"},
    )
    layout = pipeline.get_bind_group_layout(0)

    params = np.array([width, height, 0, 0], dtype=np.uint32)
    params_buf = device.create_buffer_with_data(
        data=params.tobytes(), usage=wgpu.BufferUsage.UNIFORM
    )
    storage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC
    buf_a = device.create_buffer_with_data(
        data=values.tobytes(), usage=storage
    )
    buf_b = device.create_buffer(size=values.nbytes, usage=storage)

    def bind(src, dst):
        return device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": params_buf, "offset": 0, "size": params.nbytes}},
                {"binding": 1, "resource": {"buffer": src, "offset": 0, "size": values.nbytes}},
                {"binding": 2, "resource": {"buffer": dst, "offset": 0, "size": values.nbytes}},
            ],
        )

    # Step k reads from one buffer and writes the other; the result ends up
    # in buf_a when steps is even, buf_b when odd.
    groups = (bind(buf_a, buf_b), bind(buf_b, buf_a))
    final = buf_a if steps % 2 == 0 else buf_b

    encoder = device.create_command_encoder()
    if steps > 0:
        cpass = encoder.begin_compute_pass()
        cpass.set_pipeline(pipeline)
        groups_x = (width + WORKGROUP - 1) // WORKGROUP
        groups_y = (height + WORKGROUP - 1) // WORKGROUP
        for k in range(steps):
            cpass.set_bind_group(0, groups[k % 2])
            cpass.dispatch_workgroups(groups_x, groups_y)
        cpass.end()
    device.queue.submit([encoder.finish()])

    data = device.queue.read_buffer(final, 0, values.nbytes)
    return np.frombuffer(data, dtype=np.uint32).copy().reshape(height, width)


def main(argv):
    if len(argv) != 2:
        print("usage: main.py <grid-file>", file=sys.stderr)
        return 2
    width, height, steps, values = read_grid(argv[1])
    grid = diffuse(width, height, steps, values)

    lines = [" ".join(map(str, row)) for row in grid.tolist()]
    total = int(grid.astype(np.uint64).sum())
    lines.append(f"SUM {total}")
    sys.stdout.write("\n".join(lines) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

